import{_ as e,o as i,c as d,ag as a}from"./chunks/framework.BLV0JUXI.js";const u=JSON.parse('{"title":"2.1 基础入门：HBuilderX 可视化搭建（Windows/macOS）","description":"在 Windows 与 macOS 上安装 HBuilderX、各端运行基座与微信开发者工具。","frontmatter":{"title":"2.1 基础入门：HBuilderX 可视化搭建（Windows/macOS）","description":"在 Windows 与 macOS 上安装 HBuilderX、各端运行基座与微信开发者工具。","tags":["环境搭建","HBuilderX","Windows","macOS"],"version":"3.2.0","difficulty":1},"headers":[],"relativePath":"guide/02-env/basics.md","filePath":"guide/02-env/basics.md","lastUpdated":1793196275000}'),o={name:"guide/02-env/basics.md"};function l(r,t,n,s,p,h){return i(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="_2-1-基础入门-hbuilderx-可视化搭建-windows-macos" tabindex="-1">2.1 基础入门：HBuilderX 可视化搭建（Windows/macOS） <a class="header-anchor" href="#_2-1-基础入门-hbuilderx-可视化搭建-windows-macos" aria-label="Permalink to &quot;2.1 基础入门：HBuilderX 可视化搭建（Windows/macOS）&quot;">​</a></h1><p>HBuilderX 是 DCloud 官方 IDE，对 uni-app 的 App 真机运行、云打包支持最好。初学者建议先用它建立正反馈，再切换到 CLI（<a href="/uniapp-tutorial-pages/guide/02-env/advanced">2.2</a>）。</p><h2 id="环境总清单" tabindex="-1">环境总清单 <a class="header-anchor" href="#环境总清单" aria-label="Permalink to &quot;环境总清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>Windows</th><th>macOS</th></tr></thead><tbody><tr><td>HBuilderX 正式版</td><td>建项目/运行/App 打包</td><td>✅ 下载正式版安装包</td><td>✅ 下载 .dmg（区分 Intel/Apple 芯片）</td></tr><tr><td>微信开发者工具</td><td>编译/预览/调试微信小程序</td><td>✅ 稳定版</td><td>✅ 稳定版</td></tr><tr><td>Chrome/Edge</td><td>H5 调试</td><td>✅</td><td>✅</td></tr><tr><td>手机数据线 + 基座</td><td>App 真机运行</td><td>Android 开 USB 调试</td><td>iOS 需信任证书</td></tr><tr><td>Node.js + pnpm</td><td>CLI 模式才需要（2.2）</td><td>LTS 版</td><td>LTS 版</td></tr></tbody></table><blockquote><p>HBuilderX 自带了 uni-app 编译器，<strong>仅用 HBuilderX 开发时不需要安装 Node.js</strong>。但本教程从 2.2 起全面采用 CLI，建议都装上。</p></blockquote><h2 id="windows-安装要点" tabindex="-1">Windows 安装要点 <a class="header-anchor" href="#windows-安装要点" aria-label="Permalink to &quot;Windows 安装要点&quot;">​</a></h2><ol><li>从 DCloud 官网下载 <strong>HBuilderX 正式版</strong>（不要用 Alpha 版做生产项目），解压到非系统保护目录，例如 <code>D:\\dev\\HBuilderX</code>（避免 <code>Program Files</code> 的写权限问题）。</li><li>微信开发者工具安装后：设置 → 安全设置 → 开启<strong>服务端口</strong>，否则 HBuilderX 无法唤起编译。</li><li>Android 真机：设置 → 关于手机 → 连点版本号开启开发者模式 → 打开 <strong>USB 调试</strong>；安装驱动（多数品牌手机助手会自动装）。</li><li>命令行偏好（可选）：使用 PowerShell 7 / Windows Terminal；若执行 <code>pnpm</code> 提示策略限制，执行：</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-ExecutionPolicy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope CurrentUser RemoteSigned</span></span></code></pre></div><ol start="5"><li>路径中避免中文与空格的老问题在新版已大幅改善，但团队项目仍建议统一使用英文路径。</li></ol><h2 id="macos-安装要点" tabindex="-1">macOS 安装要点 <a class="header-anchor" href="#macos-安装要点" aria-label="Permalink to &quot;macOS 安装要点&quot;">​</a></h2><ol><li>Apple 芯片（M 系列）与 Intel 芯片下载不同的 dmg，选错版本会出现 Rosetta 相关异常或性能损失。</li><li>首次启动若提示「无法验证开发者」，到 <strong>系统设置 → 隐私与安全性</strong> 中允许打开。</li><li>iOS 真机调试：数据线连接后在手机上点「信任此电脑」；标准基座由 HBuilderX 签名安装，个人免费 Apple ID 也可真机调试，但应用 7 天后需重装。</li><li>微信开发者工具同样需要开启服务端口；macOS 上还要授权「辅助功能/完全磁盘访问」视提示而定。</li><li>推荐通过 Homebrew 安装 Node 生态：<code>brew install node pnpm</code>（或使用 fnm/nvm 管理多版本）。</li></ol><h2 id="创建并运行第一个项目" tabindex="-1">创建并运行第一个项目 <a class="header-anchor" href="#创建并运行第一个项目" aria-label="Permalink to &quot;创建并运行第一个项目&quot;">​</a></h2><ol><li>HBuilderX → 文件 → 新建 → 项目 → uni-app → 选 <strong>Vue 3 模板</strong>，勾选 TypeScript。</li><li>顶部菜单「运行」提供四个目标：</li></ol><ul><li><strong>运行到浏览器</strong>：直接选 Chrome/Edge，HBuilderX 内置终端会打印本地地址。</li><li><strong>运行到小程序模拟器</strong>：首次需配置微信开发者工具路径。</li><li><strong>运行到手机或模拟器</strong>：真机用标准基座；Android 模拟器可用各品牌自带模拟器或第三方。</li><li><strong>运行到 App 基座</strong>：基座是一个带调试能力的宿主 App，开发阶段代码热更到基座中。</li></ul><h2 id="微信开发者工具联调配置" tabindex="-1">微信开发者工具联调配置 <a class="header-anchor" href="#微信开发者工具联调配置" aria-label="Permalink to &quot;微信开发者工具联调配置&quot;">​</a></h2><ol><li>HBuilderX → 工具 → 设置 → 运行配置 → 填写微信开发者工具安装路径。</li><li>微信开发者工具 → 设置 → 安全设置 → 服务端口：开启。</li><li>编译产物默认输出到项目的 <code>dist/dev/mp-weixin</code>，微信开发者工具应<strong>导入该目录</strong>而不是项目根目录（HBuilderX 会自动唤起；CLI 模式需手动导入一次）。</li><li>在微信开发者工具里：</li></ol><ul><li><strong>AppData</strong> 面板看页面数据（相当于 Vue devtools 的数据视图）</li><li><strong>Console/Network</strong> 看日志与请求</li><li><strong>Wxml</strong> 面板看真实小程序节点</li></ul><h2 id="app-真机运行的两种基座" tabindex="-1">App 真机运行的两种基座 <a class="header-anchor" href="#app-真机运行的两种基座" aria-label="Permalink to &quot;App 真机运行的两种基座&quot;">​</a></h2><table tabindex="0"><thead><tr><th>基座</th><th>用途</th><th>特点</th></tr></thead><tbody><tr><td>标准基座</td><td>日常开发调试</td><td>HBuilderX 签名，随编译器更新，开箱即用</td></tr><tr><td>自定义基座</td><td>测试原生插件、推送、支付等 SDK</td><td>需在 manifest 勾选模块后制作，包名/证书与正式包一致</td></tr></tbody></table><p>经验法则：<strong>功能在标准基座正常但自定义基座异常，优先排查模块勾选与基座版本是否过期</strong>（重新制作基座通常能解决一半问题）。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：HBuilderX 编译卡住或提示插件下载失败？</strong> 网络问题居多。检查代理；企业网络下切换到手机热点验证，确认是网络而非项目问题后再配置镜像。</p><p><strong>Q：Windows 上微信开发者工具打不开编译产物？</strong> 先确认服务端口已开启，再检查项目路径是否过深/含特殊字符；CLI 项目确认导入的是 <code>dist/dev/mp-weixin</code>。</p><p><strong>Q：macOS 上 M 芯片模拟器/Android 模拟器很慢？</strong> Android Emulator 确认安装的是 arm64 系统镜像；iOS 模拟器只支持部分 uni-app 能力，重能力（推送、蓝牙）请直接真机。</p><p><strong>Q：HBuilderX 要不要登录账号？</strong> 云打包、uniCloud 等服务需要 DCloud 账号；本地编译运行不需要。</p><p>下一篇 <a href="/uniapp-tutorial-pages/guide/02-env/advanced">2.2 CLI + Vite + TypeScript 工程化环境</a> 将用 pnpm 搭建可进 CI、可团队协作的命令行工程。</p>',26)])])}const g=e(o,[["render",l]]);export{u as __pageData,g as default};
